class Solution {
public:
    vector<int> loudAndRich(vector<vector<int>>& richer, vector<int>& quiet) {
        int n = quiet.size();
        vector<vector<int>> adj(n);
        for (auto& r : richer) {
            adj[r[1]].push_back(r[0]);
        }
        vector<int> ans(n, -1);
        auto dfs = [&](auto& self, int node) -> int {
            if (ans[node] != -1) return ans[node];
            int best = node;
            for (int neighbor : adj[node]) {
                int cand = self(self, neighbor);
                if (quiet[cand] < quiet[best]) best = cand;
            }
            return ans[node] = best;
        };
        for (int i = 0; i < n; i++) dfs(dfs, i);
        return ans;
    }
};

class Solution {
    public int[] loudAndRich(int[][] richer, int[] quiet) {
        int n = quiet.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] r : richer) {
            adj.get(r[1]).add(r[0]);
        }
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            dfs(i, adj, quiet, ans);
        }
        return ans;
    }

    private int dfs(int node, List<List<Integer>> adj, int[] quiet, int[] ans) {
        if (ans[node] != -1) return ans[node];
        int best = node;
        for (int neighbor : adj.get(node)) {
            int cand = dfs(neighbor, adj, quiet, ans);
            if (quiet[cand] < quiet[best]) best = cand;
        }
        ans[node] = best;
        return best;
    }
}

var loudAndRich = function(richer, quiet) {
    const n = quiet.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of richer) {
        adj[v].push(u);
    }
    const ans = new Array(n).fill(-1);
    const dfs = (node) => {
        if (ans[node] !== -1) return ans[node];
        let best = node;
        for (const neighbor of adj[node]) {
            const cand = dfs(neighbor);
            if (quiet[cand] < quiet[best]) best = cand;
        }
        ans[node] = best;
        return best;
    };
    for (let i = 0; i < n; i++) dfs(i);
    return ans;
};
